import { z } from "zod";

/**
 * A single candidate question pre-generated by the prediction worker.
 */
export const CandidateQuestionSchema = z.object({
  text: z.string().min(1),
  type: z.enum(["follow-up", "probe", "scenario"]),
  /**
   * Model-reported confidence 0–1.
   * Used only as a tiebreaker inside the local decision engine.
   * Never used alone as a gate.
   */
  confidence: z.number().min(0).max(1),
  topic: z.string(),
});

export type CandidateQuestion = z.infer<typeof CandidateQuestionSchema>;

/**
 * The full prediction pool stored during the candidate's turn.
 *
 * turnId ties the pool to a specific candidate utterance.
 * Predictions generated for turn 7 are invalid if the candidate
 * is now on turn 8 — they are discarded without inspection.
 */
export const PredictionPoolSchema = z.object({
  questions: z.array(CandidateQuestionSchema),
  /** Unix ms timestamp when this pool was generated. */
  generatedAt: z.number(),
  /** The interim transcript text that produced this pool. */
  interimText: z.string(),
  /** Interview phase when the pool was generated. */
  phase: z.enum(["greeting", "rapport", "technical", "wrapup", "closed"]),
  /**
   * Stable turn identifier: transcript.length at the moment the candidate
   * started speaking this turn. This is the count of all saved transcript
   * entries (AI + user) before this turn began.
   *
   * The orchestrator rejects any pool whose turnId does not match the
   * expected value derived from the final transcript length.
   */
  turnId: z.number().int().nonnegative(),
  /**
   * Sequential version within a single turn.
   * Each debounced predict call increments this. The orchestrator always
   * uses the latest version (the pool is overwritten on each call).
   * Stored for diagnostics only.
   */
  predictionVersion: z.number().int().nonnegative(),
});

export type PredictionPool = z.infer<typeof PredictionPoolSchema>;

/**
 * Request body for POST /api/interviews/[id]/predict
 */
export const PredictRequestSchema = z.object({
  interviewId: z.string().uuid(),
  interimTranscript: z.string(),
  phase: z.enum(["greeting", "rapport", "technical", "wrapup", "closed"]),
  resumeData: z
    .object({
      fullName: z.string(),
      topSkills: z.array(z.string()),
      yearsOfExperience: z.number(),
      coreProjects: z.array(
        z.object({
          title: z.string(),
          description: z.string(),
        }),
      ),
    })
    .optional(),
  recentTranscript: z.array(
    z.object({
      speaker: z.enum(["user", "ai"]),
      content: z.string(),
    }),
  ),
  /**
   * The stable turn ID: transcript.length at the moment this candidate
   * utterance began. Forwarded into the pool so the orchestrator can
   * validate the pool belongs to the current turn.
   */
  turnId: z.number().int().nonnegative(),
  /**
   * Monotonically increasing prediction version within this turn.
   * Incremented by the browser's debounce logic each time predict fires.
   */
  predictionVersion: z.number().int().nonnegative(),
});

export type PredictRequest = z.infer<typeof PredictRequestSchema>;
